const t=k=>messages[lang][k] || messages.en[k] || k;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let displayTimezone=localStorage.getItem('sacho-timezone')||'';try{if(displayTimezone)new Intl.DateTimeFormat('en',{timeZone:displayTimezone}).format();}catch{displayTimezone='';}
const date=(ts,short=false)=>new Date(ts*1000).toLocaleString(lang==='ko'?'ko-KR':'en-US',{...(short?{month:'short',day:'numeric'}:{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit'}),...(displayTimezone?{timeZone:displayTimezone}:{})});
const state=(s)=>`<span class="state ${esc(s)}"><span class="dot"></span>${esc(t(s))}</span>`;
const empty=(title,help)=>`<div class="empty"><div class="empty-icon">✓</div><h3>${esc(t(title))}</h3><p>${esc(t(help))}</p></div>`;
function translate(root=document){root.querySelectorAll('[data-i18n]').forEach(e=>e.textContent=t(e.dataset.i18n));document.documentElement.lang=lang;$('#language').value=lang;document.querySelectorAll('[data-sacho-language]').forEach(e=>e.value=lang);if($('#timezone')){$('#timezone').setAttribute('aria-label',t('displayTimezone'));$('#timezone option[value=""]').textContent=t('systemTimezone');}}
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,4500);}
async function api(path,method='GET',body){const res=await fetch(path,{method,headers:{'Content-Type':'application/json','X-Sacho-Request':'1'},body:body===undefined?undefined:JSON.stringify(body),signal:AbortSignal.timeout(method==='GET'?15000:330000)});let value;try{value=await res.json();}catch{throw new Error(`HTTP ${res.status}`);}if(!res.ok){const e=new Error(value.error || `HTTP ${res.status}`);e.status=res.status;throw e;}return value;}
let publicData,adminItems=[],activeTab='monitors',range=90*86400,precision=86400,refreshing=false,refreshQueued=false,publicRefreshFailed=false,lastPublicLoad=-Infinity,layoutDraft=null,luaEditor=null,editId=null,logId=null,logBefore=null,dragId=null;
const isAdmin=location.pathname==='/admin'||location.pathname==='/admin/';
$('#nav-admin').classList.toggle('active',isAdmin);$('#nav-status').classList.toggle('active',!isAdmin);
function groupsFor(items,layout){const map=new Map(items.map(i=>[i.id,i]));const used=new Set();const groups=[];for(const section of layout || []){const list=section.item_ids.map(id=>map.get(id)).filter(i=>i && !used.has(i.id));list.forEach(i=>used.add(i.id));groups.push({title:section.title,items:list});}for(const item of items){if(used.has(item.id))continue;const group=item.group??item.spec.group;let section=groups.find(g=>g.title===group);if(!section){section={title:group,items:[]};groups.push(section);}section.items.push(item);}return groups;}

const rangeOptions=[[3600,'oneHour'],[21600,'sixHours'],[86400,'oneDay'],[604800,'sevenDays'],[2592000,'thirtyDays'],[7776000,'ninetyDays']];
const precisionOptions=[[5,'5s'],[10,'10s'],[30,'30s'],[60,'1m'],[300,'5m'],[1800,'30m'],[3600,'1h'],[86400,'1d']];
function minimumInterval(data){return data?.items.length?Math.min(...data.items.map(i=>i.interval_seconds)):5;}
function supportedGaps(data,window){const interval=minimumInterval(data);return precisionOptions.map(([p])=>p).filter(p=>p>=interval && p<=window/2 && Math.ceil(window/p)<=10000);}
function automaticGap(data,window){const gaps=supportedGaps(data,window);return gaps.find(p=>Math.ceil(window/p)<=180)??gaps.at(-1)??30;}
function normalizeTimeline(data){if(!supportedGaps(data,range).length){range=rangeOptions.find(([window])=>supportedGaps(data,window).length)?.[0]??7776000;}if(!supportedGaps(data,range).includes(precision))precision=automaticGap(data,range);}
function publicMarkup(data,incidents){const health=data.status;const titleKey='hero'+health[0].toUpperCase()+health.slice(1);const ranges=rangeOptions;const precisions=precisionOptions.filter(([p])=>supportedGaps(data,range).includes(p));return `<div class="intro"><p class="eyebrow">${t('serviceHealth')}</p><h1>${t('title')}</h1><p>${esc(data.site.description)}</p></div><div class="hero ${esc(health)}"><div class="hero-icon">${health==='operational'?'✓':health==='unknown'?'○':'!'}</div><div><h2>${t(titleKey)}</h2><p>${t('heroHelp')}</p></div><span class="live"><span class="dot"></span>${t('live')}</span></div><section><div class="section-head"><h2>${t('systemStatus')} <span class="monitor-count">· ${data.items.length}</span></h2><div class="controls"><select id="range" aria-label="${t('range')}">${ranges.map(([v,k])=>`<option value="${v}" ${v===range?'selected':''} ${supportedGaps(data,v).length?'':'disabled'}>${t(k)}</option>`).join('')}</select><select id="precision" aria-label="${t('precision')}">${precisions.map(([v,k])=>`<option value="${v}" ${v===precision?'selected':''}>${k}</option>`).join('')}</select></div></div>${data.items.length?`<div class="services">${groupsFor(data.items,data.site.layout).filter(g=>g.items.length).map(g=>`<div class="group-name">${esc(g.title)}</div>${g.items.map(i=>`<article class="service" data-service="${esc(i.id)}"><div class="service-head"><div><h3>${esc(i.name)}</h3>${i.description?`<p>${esc(i.description)}</p>`:''}</div><div class="service-right">${i.publish_value||i.display_value!=null?`<span class="metric ${esc(i.value_severity||'')}" title="${i.display_value_stale?t('lastKnown'):t('latest')} · ${i.display_value_at?date(i.display_value_at):t('noData')}">${i.display_label?`<small>${esc(i.display_label)} </small>`:''}${i.display_value!=null?esc(i.display_value)+esc(i.metric_unit):t('unavailableValue')}${i.display_value_stale?`<small> · ${t('lastKnown')} · ${date(i.display_value_at)}</small>`:''}</span>`:''}${state(i.status)}</div></div>${i.public_message?`<p class="muted">${esc(i.public_message)}</p>`:''}<div class="bars" aria-label="${esc(i.name)} ${t('uptime')}"><span class="spinner"></span></div><div class="axis"><span>${date(data.updated_at-range,true)}</span><span class="uptime">${t('loading')}</span><span>${date(data.updated_at,true)}</span></div>${i.publish_trend?`<div class="trend-panel"><label>${t('trend')} <select data-series="${esc(i.id)}"><option value="metric">${esc(i.display_label||t('trend'))}</option><option value="latency">${t('latency')}</option></select></label><div class="trend-chart"></div></div>`:''}<p class="freshness ${i.freshness==='stale'?'stale':''}">${i.freshness==='stale'?t('staleData')+' · ':''}${t('updated')} ${i.last_check?date(i.last_check):t('noData')} · ${t('lastHealthy')} ${i.last_success?date(i.last_success):t('noData')} · ${t('nextCheck')} ${date(i.next_check)}</p><p class="detail" hidden></p></article>`).join('')}`).join('')}</div>`:empty('noServices','noServicesHelp')}<div class="legend">${['operational','degraded','outage','unknown'].map(s=>`<span><i class="dot ${s}"></i>${s==='unknown'?t('noData'):t(s)}</span>`).join('')}</div><p class="footnote">${t('footnote')}</p></section><section class="history"><div class="section-head"><h2>${t('incidentHistory')}</h2><span class="muted">${incidents.length?incidents.length:''}</span></div>${incidents.length?incidents.map(i=>`<article class="incident"><div class="incident-top"><h3>${esc(i.name)}</h3><span class="badge ${esc(i.status)}">${t(i.status)}</span></div><p>${date(i.opened_at)}${i.resolved_at?` → ${date(i.resolved_at)}`:` · ${t('live')}`}</p></article>`).join(''):empty('noIncidents','noIncidentsHelp')}</section>`;}
async function renderHistory(item,to){const row=$(`[data-service="${item.id}"]`);if(!row)return;try{const from=Math.floor((to-range)/precision)*precision;const result=await api(`/api/history/${item.id}?from=${to+1-range}&to=${to+1}&precision=${precision}`);if(!row.isConnected)return;const count=Math.ceil((to+1-from)/precision);const bucketMap=new Map(result.buckets.map(b=>[b.at,b]));let samples=0,healthy=0;const bars=[];const chart=$('.bars',row),gap=parseFloat(getComputedStyle(chart).gap)||3,capacity=Math.max(1,Math.min(180,Math.floor((chart.clientWidth+gap)/(2+gap))));const stride=Math.max(1,Math.ceil(count/capacity));
for(let n=0;n<count;n+=stride){const at=from+n*precision;let groupSamples=0,groupHealthy=0,latency=0,severity=-1;for(let k=n;k<Math.min(n+stride,count);k++){const b=bucketMap.get(from+k*precision);if(!b)continue;groupSamples+=b.samples;groupHealthy+=b.healthy;latency+=b.latency_ms*b.samples;severity=Math.max(severity,b.severity);}samples+=groupSamples;healthy+=groupHealthy;const s=severity===2?'outage':severity===1?'degraded':severity===0?'operational':'unknown';const end=Math.min(to+1,at+stride*precision);const label=`${date(at)} → ${date(end)} · ${groupSamples?`${t(s)} · ${groupSamples} ${t('checks')} · ${t('average')}  ${Math.round(latency/groupSamples)} ms`:t('noData')}`;bars.push(`<button class="bar ${s}" aria-label="${esc(label)}" data-bucket="${esc(label)}"></button>`);}
$('.bars',row).innerHTML=bars.join('');if(item.publish_trend){trendData.set(item.id,{item,result});$('.trend-chart',row).innerHTML=trendMarkup(item,result,graphModes.get(item.id)||'metric');$('[data-series]',row).value=graphModes.get(item.id)||'metric';}$('.uptime',row).textContent=samples?`${(100*healthy/samples).toFixed(2)}% ${t('uptime')} · ${item.latency_ms??'—'} ms`:t('noData');}catch(e){$('.bars',row).innerHTML='';$('.uptime',row).textContent=e.message;}}
async function loadPublic(){if(refreshing){refreshQueued=true;return;}refreshing=true;try{const [data,incidents]=await Promise.all([api('/api/status'),api('/api/incidents')]);publicData=data;normalizeTimeline(data);$('#brand-title').textContent=data.site.title;document.title=`${data.site.title} · ${t('statusPage')}`;$('#subscribe-open').disabled=!data.subscriptions_enabled;$('#subscribe-open').title=data.subscriptions_enabled?'':t('subscriptionsDisabled');hideTooltip();$('#app').innerHTML=publicMarkup(data,incidents);$('#refresh-time').textContent=`${t('updated')} ${date(data.updated_at)}`;let next=0;await Promise.all(Array.from({length:Math.min(4,data.items.length)},async()=>{while(next<data.items.length){const i=data.items[next++];await renderHistory(i,data.updated_at);}}));lastPublicLoad=performance.now();publicRefreshFailed=false;}catch(e){publicRefreshFailed=true;if(publicData){if(!$('.refresh-error'))$('#app').insertAdjacentHTML('afterbegin',`<div class="refresh-error">${t('errorRefresh')}</div>`);}else{$('#app').innerHTML=`<div class="empty">${esc(e.message)}</div>`;}}finally{refreshing=false;if(refreshQueued){refreshQueued=false;loadPublic();}}}
function workerOptions(selected){const select=$('#edit-form').elements.worker;const current=selected??select.value;select.innerHTML=`<option value="">${esc(t('localNode'))}</option>${adminWorkers.filter(w=>!w.revoked).map(w=>`<option value="${esc(w.id)}">${esc(w.label||w.id)} · ${esc(w.id)}</option>`).join('')}`;if(current&&!adminWorkers.some(w=>w.id===current&&!w.revoked)){const option=document.createElement('option');option.value=current;option.textContent=`${current} · ${t('workerUnavailable')}`;select.append(option);}select.value=current;}
function workerPanel(){return `<div class="panel"><h2>${t('workers')}</h2><form id="bootstrap-form"><div class="form-grid"><label>${t('nodeId')}<input name="node_id" required maxlength="64" pattern="[A-Za-z0-9_\\-]+"></label><label>${t('bootstrapExpiry')}<select name="ttl_seconds"><option value="300">5 min</option><option value="900" selected>15 min</option><option value="3600">1 h</option></select></label><label class="checkbox"><input name="allow_scripts" type="checkbox">${t('scriptPermission')}</label></div><button class="primary">${t('createBootstrap')}</button></form>${bootstrapResult?`<div class="panel"><h3>${t('bootstrapKey')} · ${esc(bootstrapResult.node_id)}</h3><p>${esc(t('bootstrapHelp'))}</p><textarea readonly aria-label="${esc(t('bootstrapKey'))}">${esc(bootstrapResult.bootstrap_key)}</textarea><p>${date(bootstrapResult.expires_at)}</p><code>sacho worker-join --config worker.toml</code><button data-action="clear-bootstrap">${t('clearBootstrap')}</button></div>`:''}<div id="worker-records">${workerRecords()}</div></div>`;}
function adminShell(){const enabled=adminItems.filter(i=>i.spec.enabled);const stats=[['activeMonitors',enabled.length,''],['healthyMonitors',enabled.filter(i=>i.status==='operational').length,'operational'],['attentionMonitors',enabled.filter(i=>['degraded','outage'].includes(i.status)).length,enabled.some(i=>i.status==='outage')?'outage':'degraded'],['pausedMonitors',adminItems.length-enabled.length,'unknown']];return `<div class="admin-head"><div><p class="eyebrow">SACHO · ${t('admin').toUpperCase()}</p><h1>${t('adminTitle')}</h1><p class="muted">${t('adminSubtitle')}</p></div><div class="admin-head-actions"><button class="outline" data-action="refresh-admin">${t('refreshAdmin')}</button><button class="primary" data-action="add">${t('addService')}</button></div></div><div class="admin-overview" aria-label="${t('monitorSummary')}">${stats.map(([label,count,cls])=>`<div class="summary-card ${cls}"><span>${t(label)}</span><strong>${count}</strong></div>`).join('')}</div><div class="admin-workspace"><aside class="admin-nav"><p class="eyebrow">${t('navigation')}</p><div class="tabs">${['monitors','workers','catalogue','inputsTab','layout','notifications','settings'].map(k=>`<button class="tab ${activeTab===k?'active':''}" data-tab="${k}"><span>${t(k)}</span>${['monitors','workers'].includes(k)?`<small aria-hidden="true">${k==='monitors'?adminItems.length:adminWorkers.filter(w=>!w.revoked).length}</small>`:''}</button>`).join('')}</div></aside><section id="admin-content"></section></div>`;}

async function loadAdmin(){try{const [items,workers]=await Promise.all([api('/api/admin/items'),api('/api/admin/workers')]);adminItems=items;adminWorkers=workers;workerOptions();$('#app').innerHTML=adminShell();await renderTab();}catch(e){$('#app').innerHTML=e.status===401?`<div class="auth-empty"><p class="eyebrow">SACHO · ADMIN</p><h2>${t('authRequired')}</h2><p class="muted">${t('authHelp')}</p><a class="outline" href="/admin">${t('authRetry')}</a></div>`:`<div class="empty">${esc(e.message)}</div>`;}}
async function renderTab(){const root=$('#admin-content');if(!root)return;try{if(activeTab==='monitors'){renderMonitors();}
else if(activeTab==='workers'){adminWorkers=await api('/api/admin/workers');workerOptions();root.innerHTML=workerPanel();}
else if(activeTab==='catalogue'){const data=await api('/api/admin/examples');exampleSpecs=data;root.innerHTML=`<div class="example-grid">${data.map(e=>`<article class="panel"><h2>${esc(e.title)}</h2><p>${esc(e.requirements)}</p><p>${t('requiredInputs')}: ${e.inputs.map(esc).join(', ')||'—'}</p><button class="outline" data-action="use-example" data-id="${esc(e.id)}">${t('useExample')}</button></article>`).join('')}</div>`;}
else if(activeTab==='inputsTab'){root.innerHTML=inputPanel(await api('/api/admin/inputs'));}
else if(activeTab==='settings'){const data=await api('/api/admin/settings');root.innerHTML=`<div class="panel"><h2>${t('siteSettings')}</h2><form id="site-form"><div class="form-grid"><label class="full">${t('name')}<input name="title" value="${esc(data.site.title)}" maxlength="120" required></label><label class="full">${t('description')}<textarea name="description" maxlength="2000">${esc(data.site.description)}</textarea></label></div><button class="primary">${t('savePage')}</button></form></div><div class="panel"><h2>${t('exportConfig')}</h2><p>${t('exportHelp')}</p><button class="outline" data-action="export-config">${t('exportConfig')}</button></div><div class="panel"><h2>${t('externalSettings')}</h2><p>${t('externalHelp')}</p><pre>${esc(JSON.stringify({auth:data.auth,smtp:data.smtp,updates:data.updates,retention_days:data.retention_days,version:data.version,target:data.target},null,2))}</pre></div>`;}
else if(activeTab==='notifications'){const [hooks,subs,deliveries,templates,policy]=await Promise.all([api('/api/admin/webhooks'),api('/api/admin/subscribers'),api('/api/admin/notifications'),api('/api/admin/templates'),api('/api/admin/notification-policy')]);root.innerHTML=`${policyPanel(policy)}${templatePanel(templates)}<div class="panel"><h2>${t('webhooks')}</h2><form id="webhook-form" class="inline-form"><label>${t('name')}<input name="name" required maxlength="120"></label><label>${t('webhookUrl')}<input name="url" type="url" required placeholder="https://example.com/hook"></label><button class="primary">${t('addWebhook')}</button></form>${table([t('name'),t('webhookUrl'),''],hooks.map(h=>[esc(h.name),esc(h.url),`<button class="danger" data-action="delete-hook" data-id="${h.id}">${t('delete')}</button>`]))}</div><div class="panel"><h2>${t('subscribers')}</h2>${table([t('email'),t('status'),t('time'),''],subs.map(s=>[esc(s.email),t(s.verified?'verified':'pending'),date(s.created_at),`<button class="danger" data-action="delete-sub" data-id="${s.id}">${t('delete')}</button>`]))}</div><div class="panel"><h2>${t('deliveryLog')}</h2>${table([t('kindLabel'),t('destination'),t('status'),t('attempts'),t('time')],deliveries.map(d=>[esc(d.kind),esc(d.destination),`<span title="${esc(d.error??'')}">${t(d.delivered_at?'delivered':d.error?.startsWith('suppressed:')?'suppressed':d.attempts>=(d.max_attempts||8)?'failed':'retrying')}</span>`,d.attempts,date(d.created_at)]))}</div>`;}
else if(activeTab==='layout'){if(!layoutDraft){const data=await api('/api/admin/settings');layoutDraft=groupsFor(adminItems,data.site.layout).map(g=>({title:g.title,item_ids:g.items.map(i=>i.id)}));}renderLayout();}}catch(e){root.innerHTML=`<div class="empty">${esc(e.message)}</div>`;}}
function table(headers,rows){return rows.length?`<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(cell=>`<td>${cell}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:`<p class="muted">${t('noData')}</p>`;}
function renderLayout(){const root=$('#admin-content');root.innerHTML=`<div class="panel"><h2>${t('layout')}</h2><p>${t('layoutHelp')}</p><div class="layout-toolbar"><button class="outline" data-action="add-section">${t('addSection')}</button><button class="outline" data-action="reset-layout">${t('resetLayout')}</button><button class="outline" data-action="preview-layout">${t('preview')}</button><button class="primary" data-action="save-layout">${t('saveLayout')}</button></div><div class="layout-sections">${layoutDraft.map((g,n)=>`<section class="layout-section" data-section="${n}"><div class="layout-section-head"><input value="${esc(g.title)}" data-section-name="${n}" aria-label="${t('sectionName')}" maxlength="120"><button data-action="section-up" data-index="${n}" title="${t('moveUp')}">↑</button><button data-action="section-down" data-index="${n}" title="${t('moveDown')}">↓</button><button data-action="delete-section" data-index="${n}" title="${t('deleteSection')}">×</button></div><div class="layout-drop" data-drop-section="${n}">${g.item_ids.map(id=>{const item=adminItems.find(i=>i.id===id);if(!item)return '';return `<div class="layout-card" draggable="true" data-drag-id="${id}"><span class="drag-handle" aria-hidden="true">⠿</span><div><strong>${esc(item.spec.name)}</strong><small>${esc(item.spec.kind)} · ${item.spec.interval_seconds}s</small></div><div class="layout-card-controls"><button data-action="item-up" data-id="${id}" aria-label="${t('moveUp')}">↑</button><button data-action="item-down" data-id="${id}" aria-label="${t('moveDown')}">↓</button><select data-move-id="${id}" aria-label="${t('moveTo')}">${layoutDraft.map((s,idx)=>`<option value="${idx}" ${idx===n?'selected':''}>${esc(s.title)}</option>`).join('')}</select></div></div>`;}).join('')}<span class="drop-hint">${t('moveTo')}</span></div></section>`).join('')}</div><div id="layout-preview"></div></div>`;}
function moveCard(id,section,before){for(const s of layoutDraft)s.item_ids=s.item_ids.filter(i=>i!==id);const ids=layoutDraft[section].item_ids;const index=ids.indexOf(before);if(index<0)ids.push(id);else ids.splice(index,0,id);renderLayout();}
function formSpec(){const f=$('#edit-form');const data=Object.fromEntries(new FormData(f));const basis=editId?adminItems.find(i=>i.id===editId)?.spec??{}:{};const spec={...basis,...data};for(const k of ['initial_delay_seconds','interval_seconds','timeout_seconds','expected_status','expected_exit','failure_threshold','recovery_threshold'])spec[k]=Number(data[k]);for(const k of ['threshold','degraded_ms'])spec[k]=data[k]===''?null:Number(data[k]);for(const k of ['enabled','publish_value','publish_trend'])spec[k]=f.elements[k].checked;spec.dns_expected=(data.dns_expected||'').split('\n').map(s=>s.trim()).filter(Boolean);spec.actions=readActions(f);for(const k of Object.keys(spec))if(k.startsWith('action_'))delete spec[k];spec.headers_env=JSON.parse(data.headers_env || '{}');spec.required_env=(data.required_env||'').split(',').map(s=>s.trim()).filter(Boolean);spec.value_rules=data.rule_warning===''&&data.rule_critical===''?null:{pointer:data.rule_pointer,direction:data.rule_direction,warning:data.rule_warning===''?null:Number(data.rule_warning),critical:data.rule_critical===''?null:Number(data.rule_critical)};for(const k of ['rule_pointer','rule_direction','rule_warning','rule_critical'])delete spec[k];return spec;}
function updateDraftLocation(){const remote=Boolean($('#edit-form').elements.worker.value);const push=$('#edit-form').elements.kind.value==='push';$('#test-draft').disabled=remote||push;$('.test-help').textContent=t(push?'pushTokenHelp':remote?'remoteDraftHelp':'testHelp');}
function mountEditor(){const f=$('#edit-form');document.querySelectorAll('[data-source-kind]').forEach(e=>e.hidden=e.dataset.sourceKind!==f.elements.kind.value);updateDraftLocation();if(f.elements.kind.value==='lua'){if(!luaEditor)luaEditor=createLuaEditor(f.elements.target,{context:'policy',label:lang==='ko'?'Lua 시나리오 편집기':'Lua scenario editor'});else luaEditor.syncFromTextarea();}else{luaEditor?.destroy();luaEditor=null;}}
function editItem(id){editId=id??null;const f=$('#edit-form');f.reset();const item=adminItems.find(i=>i.id===id);workerOptions(item?.spec.worker||'');if(item){fillRules(item.spec);for(const [k,v]of Object.entries(item.spec)){const input=f.elements[k];if(!input)continue;if(input.type==='checkbox')input.checked=v;else input.value=k==='headers_env'?JSON.stringify(v):k==='required_env'?v.join(', '):k==='dns_expected'?v.join('\n'):v??'';}}else{f.elements.metric_unit.value='';}renderActionFields(item?.spec.actions||[]);$('#edit-title').textContent=item?t('edit'):t('addService');$('#edit-error').textContent='';$('#draft-result').hidden=true;$('#validation-result').hidden=true;$('#example-inputs').hidden=true;mountEditor();updateDraftLocation();$('#edit-dialog').showModal();}
async function loadLogs(id,append=false){if(!append){logId=id;logBefore=null;$('#logs-title').textContent=adminItems.find(i=>i.id===id)?.spec.name??'';$('#logs-content').innerHTML='';$('#logs-dialog').showModal();}try{const rows=await api(`/api/admin/items/${id}/logs?limit=30${logBefore?'&before='+logBefore:''}`);$('#logs-content').insertAdjacentHTML('beforeend',rows.map(r=>`<article class="log-row"><div class="log-head"><span>${date(r.at)}</span>${state(r.status)}<span>${r.latency_ms} ms</span></div>${r.detail?`<p class="log-detail">${esc(r.detail)}</p>`:''}<details><summary>stdout / stderr</summary><pre>${esc(r.output||'—')}</pre></details></article>`).join(''));logBefore=rows.at(-1)?.id??null;$('#logs-more').hidden=rows.length<30;if(!rows.length&&!append)$('#logs-content').innerHTML=`<p class="muted">${t('noData')}</p>`;}catch(e){toast(e.message);}}
document.addEventListener('click',async e=>{const section=e.target.closest('[data-edit-section]');if(section){const fieldset=$('#'+section.dataset.editSection);fieldset.focus({preventScroll:true});fieldset.scrollIntoView({block:'start',behavior:'smooth'});return;}const close=e.target.closest('[data-close]');if(close){$('#'+close.dataset.close).close();return;}const bucket=e.target.closest('[data-bucket]');if(bucket){const detail=$('.detail',bucket.closest('.service'));detail.hidden=false;detail.textContent=bucket.dataset.bucket;return;}const tab=e.target.closest('[data-tab]');if(tab){activeTab=tab.dataset.tab;if(activeTab!=='workers')bootstrapResult=null;document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t===tab));await renderTab();return;}const button=e.target.closest('[data-action]');if(!button)return;const {action,id,index}=button.dataset;try{if(action==='push-token'){if(!confirm(t('pushTokenHelp')))return;const result=await api('/api/admin/push/'+encodeURIComponent(id)+'/token','POST');$('#push-token').value=result.token;$('#push-example').textContent=`POST ${result.endpoint}\nAuthorization: Bearer <TOKEN>\nContent-Type: application/json\n\n{"status":"operational","data":{"value":123}}`;$('#push-dialog').showModal();}else if(action==='push-revoke'){if(!confirm(t('confirmDelete')))return;await api('/api/admin/push/'+encodeURIComponent(id)+'/token','DELETE');toast(t('saved'));}else if(action==='input-replace'){const form=$('#input-form');form.elements.name.value=id;form.elements.value.value='';form.elements.enabled.checked=button.dataset.enabled==='true';form.elements.value.focus();}else if(action==='input-delete'){if(!confirm(t('confirmDelete')))return;await api('/api/admin/inputs/'+encodeURIComponent(id),'DELETE');await renderTab();}else if(action==='refresh-admin'){await loadAdmin();}else if(action==='clear-filters'){monitorQuery='';monitorFilter='';monitorLocation='all';renderMonitors();}else if(action==='use-example'){const example=exampleSpecs.find(e=>e.id===id);editItem();fillSpec(example.spec);$('#example-inputs').hidden=false;$('#example-inputs').textContent=t('requiredInputs')+': '+(example.inputs.join(', ')||'—')+' · '+example.requirements;}else if(action==='export-config'){const data=await api('/api/admin/export');const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)+'\n'],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='sacho-monitor-metadata.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}else if(action==='clear-maintenance'){const form=$('#policy-form');form.elements.maintenance_until.value='';await savePolicy(form);await renderTab();}else if(action==='clear-bootstrap'){bootstrapResult=null;await renderTab();}else if(action==='revoke-worker'){if(!confirm(t('confirmDelete')))return;await api(`/api/admin/workers/${encodeURIComponent(id)}`,'DELETE');await renderTab();}else if(action==='preview-templates'){const result=await api('/api/admin/templates/preview','POST',{templates:templateSpec(),event:$('#template-form [name=preview_event]').value});const preview=$('#template-preview');preview.hidden=false;preview.textContent=JSON.stringify(result,null,2);}else if(action==='add')editItem();else if(action==='edit')editItem(id);else if(action==='logs')await loadLogs(id);else if(action==='run'){await api(`/api/admin/items/${id}/run`,'POST');toast(t('queued'));}else if(action==='retry')await loadAdmin();else if(['delete','delete-hook','delete-sub'].includes(action)){if(!confirm(t('confirmDelete')))return;const path=action==='delete'?`/api/admin/items/${id}`:action==='delete-hook'?`/api/admin/webhooks/${id}`:`/api/admin/subscribers/${id}`;await api(path,'DELETE');if(action==='delete'){layoutDraft=null;await loadAdmin();}else await renderTab();}else if(action==='add-section'){layoutDraft.push({title:t('sectionName'),item_ids:[]});renderLayout();}else if(action==='reset-layout'){layoutDraft=groupsFor(adminItems,[]).map(g=>({title:g.title,item_ids:g.items.map(i=>i.id)}));renderLayout();}else if(action==='save-layout'){await api('/api/admin/layout','PUT',{sections:layoutDraft});toast(t('saved'));}else if(action==='preview-layout'){const data=await api('/api/status');data.site.layout=layoutDraft;$('#layout-preview').innerHTML=`<h2>${t('preview')}</h2><div class="services">${groupsFor(data.items,layoutDraft).filter(g=>g.items.length).map(g=>`<div class="group-name">${esc(g.title)}</div>${g.items.map(i=>`<article class="service"><div class="service-head"><h3>${esc(i.name)}</h3>${state(i.status)}</div>${i.display_value!=null?`<p class="metric">${esc(i.display_value)}${esc(i.metric_unit)}</p>`:''}</article>`).join('')}`).join('')}</div>`;}else if(action==='delete-section'){const n=Number(index);if(layoutDraft.length===1)return;if(!confirm(t('confirmDelete')))return;const removed=layoutDraft.splice(n,1)[0];layoutDraft[0].item_ids.push(...removed.item_ids);renderLayout();}else if(action==='section-up'||action==='section-down'){const n=Number(index),next=n+(action==='section-up'?-1:1);if(next>=0&&next<layoutDraft.length){[layoutDraft[n],layoutDraft[next]]=[layoutDraft[next],layoutDraft[n]];renderLayout();}}else if(action==='item-up'||action==='item-down'){const group=layoutDraft.find(g=>g.item_ids.includes(id));const n=group.item_ids.indexOf(id),next=n+(action==='item-up'?-1:1);if(next>=0&&next<group.item_ids.length){[group.item_ids[n],group.item_ids[next]]=[group.item_ids[next],group.item_ids[n]];renderLayout();}}}catch(error){toast(error.message);}});
document.addEventListener('change',async e=>{if(e.target.id==='timezone'){displayTimezone=e.target.value;localStorage.setItem('sacho-timezone',displayTimezone);if(isAdmin)await renderTab();else await loadPublic();}else if(e.target.id==='monitor-filter'){monitorFilter=e.target.value;renderMonitorList();}else if(e.target.id==='monitor-location'){monitorLocation=e.target.value;renderMonitorList();}else if(e.target.dataset.series){const id=e.target.dataset.series;graphModes.set(id,e.target.value);const d=trendData.get(id);if(d)$('.trend-chart',e.target.closest('.service')).innerHTML=trendMarkup(d.item,d.result,e.target.value);}else if(e.target.id==='range'){range=Number(e.target.value);precision=automaticGap(publicData,range);await loadPublic();}else if(e.target.id==='precision'){precision=Number(e.target.value);await loadPublic();}else if(e.target.name==='kind'&&e.target.form?.id==='edit-form'){mountEditor();}else if(e.target.dataset.moveId){moveCard(e.target.dataset.moveId,Number(e.target.value));}});
document.addEventListener('input',e=>{if(e.target.id==='monitor-search'){monitorQuery=e.target.value;renderMonitorList();}if(e.target.name==='worker')updateDraftLocation();if(e.target.dataset.sectionName!==undefined)layoutDraft[Number(e.target.dataset.sectionName)].title=e.target.value;});
document.addEventListener('dragstart',e=>{const card=e.target.closest('[data-drag-id]');if(card){dragId=card.dataset.dragId;e.dataTransfer.setData('text/plain',dragId);e.dataTransfer.effectAllowed='move';}});
document.addEventListener('dragover',e=>{const section=e.target.closest('[data-drop-section]');if(section&&dragId){e.preventDefault();e.dataTransfer.dropEffect='move';}});
document.addEventListener('drop',e=>{const section=e.target.closest('[data-drop-section]');if(section&&dragId){e.preventDefault();const before=e.target.closest('[data-drag-id]')?.dataset.dragId;if(before!==dragId)moveCard(dragId,Number(section.dataset.dropSection),before);dragId=null;}});
document.addEventListener('dragend',()=>dragId=null);
document.addEventListener('submit',async e=>{if(!['edit-form','site-form','webhook-form','subscribe-form','template-form','bootstrap-form','policy-form','input-form'].includes(e.target.id))return;e.preventDefault();const button=e.submitter;button.disabled=true;try{if(e.target.id==='input-form'){const f=e.target;const payload={enabled:f.elements.enabled.checked};if(f.elements.value.value!=='')payload.value=f.elements.value.value;await api('/api/admin/inputs/'+encodeURIComponent(f.elements.name.value),'PUT',payload);f.elements.value.value='';await renderTab();toast(t('saved'));}else if(e.target.id==='policy-form'){await savePolicy(e.target);toast(t('saved'));}else if(e.target.id==='bootstrap-form'){bootstrapResult=await api('/api/admin/worker-bootstrap','POST',{id:e.target.elements.node_id.value,allow_scripts:e.target.elements.allow_scripts.checked,ttl_seconds:Number(e.target.elements.ttl_seconds.value)});await renderTab();}else if(e.target.id==='edit-form'){const spec=formSpec();const report=await validateSpec(spec);if(!report.valid)throw new Error(report.errors.join('\n'));await api(editId?`/api/admin/items/${editId}`:'/api/admin/items',editId?'PUT':'POST',spec);$('#edit-dialog').close();layoutDraft=null;await loadAdmin();toast(t('saved'));}else if(e.target.id==='site-form'){await api('/api/admin/settings','PUT',Object.fromEntries(new FormData(e.target)));toast(t('saved'));}else if(e.target.id==='webhook-form'){await api('/api/admin/webhooks','POST',Object.fromEntries(new FormData(e.target)));await renderTab();toast(t('saved'));}else if(e.target.id==='template-form'){await api('/api/admin/templates','PUT',templateSpec());toast(t('saved'));}else{await api('/api/subscribe','POST',{email:e.target.elements.email.value});$('#subscribe-message').textContent=t('confirmationSent');await loadAccount();}}catch(error){if(e.target.id==='edit-form')$('#edit-error').textContent=error.message;else if(e.target.id==='subscribe-form')$('#subscribe-message').textContent=error.message;else toast(error.message);}finally{button.disabled=false;}});
async function toggleLanguage(event){lang=event.target.value;localStorage.setItem('sacho-language',lang);translate();if($('#edit-dialog').open)updateDraftLocation();renderAccount();luaEditor?.setLabel(lang==='ko'?'Lua 시나리오 편집기':'Lua scenario editor');if(isAdmin){await loadAdmin();}else await loadPublic();}
$('#language').addEventListener('change',toggleLanguage);document.querySelectorAll('[data-sacho-language]').forEach(e=>e.addEventListener('change',toggleLanguage));
$('#subscribe-open').addEventListener('click',()=>{$('#subscribe-message').textContent='';if(accountData?.email)$('#subscribe-form').elements.email.value=accountData.email;$('#subscribe-dialog').showModal();});
$('#logs-more').addEventListener('click',()=>loadLogs(logId,true));
$('#edit-dialog').addEventListener('close',()=>{luaEditor?.destroy();luaEditor=null;});
$('#test-draft').addEventListener('click',async()=>{const button=$('#test-draft');button.disabled=true;const result=$('#draft-result');result.hidden=false;result.textContent=t('testing');try{const spec=formSpec();const obs=await api('/api/admin/test','POST',spec);result.textContent=`${t(obs.status)} · ${obs.latency_ms} ms\n${obs.detail || ''}\n${obs.output || ''}\n${obs.validation?.warnings?.join('\n')||''}\n${spec.publish_value&&obs.display_value==null?t('unavailableValue'):''}`;}catch(e){result.textContent=e.message;}finally{button.disabled=false;}});
translate();if(isAdmin)loadAdmin();else loadPublic();setInterval(()=>{if(!document.hidden && !isAdmin && !document.querySelector('dialog[open]') && (!publicData || publicRefreshFailed || publicData.status==='unknown' || performance.now()-lastPublicLoad>=30000))loadPublic();},5000);

let accountData=null;
function renderAccount(){const root=$('#account');root.hidden=!accountData?.email;if(root.hidden)return;root.innerHTML=`<span class="subscription-state ${accountData.subscription==='subscribed'?'subscribed':''}"><span class="dot"></span>${esc(accountData.email)} <span>${t(accountData.subscription==='pending'?'pending':accountData.subscription)}</span></span>${accountData.logout_url?`<a class="outline" href="${esc(accountData.logout_url)}">${t('logout')}</a>`:''}`;}
async function loadAccount(){try{const response=await fetch('/api/account',{headers:{Accept:'application/json'},redirect:'error',signal:AbortSignal.timeout(15000)});if(!response.ok){accountData=null;}else accountData=await response.json();renderAccount();}catch{accountData=null;renderAccount();}}
loadAccount();setInterval(()=>{if(!document.hidden)loadAccount();},30000);
let tooltipBar=null;
function hideTooltip(){tooltipBar?.removeAttribute('aria-describedby');tooltipBar=null;$('#chart-tooltip').hidden=true;}
function showTooltip(bar){if(!bar)return;hideTooltip();tooltipBar=bar;bar.setAttribute('aria-describedby','chart-tooltip');const tip=$('#chart-tooltip');tip.textContent=bar.dataset.bucket;tip.hidden=false;const rect=bar.getBoundingClientRect();tip.style.left=Math.max(8,Math.min(window.innerWidth-tip.offsetWidth-8,rect.left+rect.width/2-tip.offsetWidth/2))+'px';tip.style.top=Math.max(8,rect.top-tip.offsetHeight-10)+'px';}
document.addEventListener('pointerover',e=>{const bar=e.target.closest('[data-bucket]');if(bar)showTooltip(bar);});
document.addEventListener('pointerout',e=>{if(e.target.closest('[data-bucket]')&&!e.relatedTarget?.closest('[data-bucket]'))hideTooltip();});
document.addEventListener('focusin',e=>{const bar=e.target.closest('[data-bucket]');if(bar)showTooltip(bar);});
document.addEventListener('focusout',e=>{if(e.target.closest('[data-bucket]'))hideTooltip();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')hideTooltip();});
window.addEventListener('scroll',()=>{if(tooltipBar)showTooltip(tooltipBar);},{passive:true});let resizeTimer;window.addEventListener('resize',()=>{hideTooltip();clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(!isAdmin)loadPublic();},200);});

function refreshVisible(){if(document.hidden)return;loadAccount();if(!isAdmin&&!document.querySelector('dialog[open]'))loadPublic();}
document.addEventListener('visibilitychange',refreshVisible);
window.addEventListener('online',refreshVisible);

function templatePanel(data){const fields=[['subject','emailSubject'],['body','emailBody'],['verification_subject','verifySubject'],['verification_body','verifyBody'],['webhook_body','webhookTemplate']];return `<div class="panel"><h2>${t('templates')}</h2><p>${t('templateHelp')}</p><p class="template-variables">${data.variables.map(name=>`<code>{{ ${esc(name)} }}</code>`).join(' ')}</p><form id="template-form"><div class="form-grid">${fields.map(([name,label])=>`<label class="full">${t(label)}<textarea name="${name}" rows="${name.includes('subject')?1:4}" maxlength="8192" ${name==='webhook_body'?'':'required'}>${esc(data.templates[name]??'')}</textarea></label>`).join('')}<label>${t('previewEvent')}<select name="preview_event"><option value="incident.started">incident.started</option><option value="incident.resolved">incident.resolved</option><option value="subscription.verify">subscription.verify</option></select></label></div><button type="button" class="outline" data-action="preview-templates">${t('previewTemplates')}</button> <button class="primary">${t('saveTemplates')}</button></form><pre id="template-preview" hidden></pre></div>`;}
function templateSpec(){const form=$('#template-form');return Object.fromEntries(['subject','body','verification_subject','verification_body','webhook_body'].map(name=>[name,name==='webhook_body'&&!form.elements[name].value.trim()?null:form.elements[name].value]));}

let exampleSpecs=[],trendData=new Map(),graphModes=new Map();
function fillRules(spec){const f=$('#edit-form');f.elements.rule_pointer.value=spec.value_rules?.pointer||'';f.elements.rule_direction.value=spec.value_rules?.direction||'low';f.elements.rule_warning.value=spec.value_rules?.warning??'';f.elements.rule_critical.value=spec.value_rules?.critical??'';}
function fillSpec(spec){const f=$('#edit-form');for(const [k,v]of Object.entries(spec)){const field=f.elements[k];if(!field)continue;if(field.type==='checkbox')field.checked=v;else field.value=k==='headers_env'?JSON.stringify(v):k==='required_env'?v.join(', '):k==='dns_expected'?v.join('\n'):v??'';}fillRules(spec);renderActionFields(spec.actions||[]);mountEditor();updateDraftLocation();}
async function validateSpec(spec){const report=await api('/api/admin/validate','POST',spec);const el=$('#validation-result');el.hidden=false;el.textContent=[report.valid?t('validConfig'):'',...report.errors,...report.warnings].filter(Boolean).join('\n');return report;}
$('#validate-draft').addEventListener('click',async()=>{try{await validateSpec(formSpec());}catch(e){$('#edit-error').textContent=e.message;}});
function localDateTime(at){return at?new Date(at*1000-new Date(at*1000).getTimezoneOffset()*60000).toISOString().slice(0,16):'';}
function policyPanel(p){return `<div class="panel"><h2>${t('notificationPolicy')}</h2><p>${t('policyHelp')}</p><form id="policy-form"><div class="form-grid"><label>${t('settleSeconds')}<input name="settle_seconds" type="number" min="0" max="3600" value="${p.settle_seconds}" required></label><label>${t('cooldownSeconds')}<input name="cooldown_seconds" type="number" min="0" max="86400" value="${p.cooldown_seconds}" required></label><label>${t('maintenanceUntil')}<input name="maintenance_until" type="datetime-local" value="${localDateTime(p.maintenance_until)}"></label></div><button class="primary">${t('save')}</button> <button type="button" class="outline" data-action="clear-maintenance">${t('clearMaintenance')}</button></form></div>`;}
async function savePolicy(form){await api('/api/admin/notification-policy','PUT',{settle_seconds:Number(form.elements.settle_seconds.value),cooldown_seconds:Number(form.elements.cooldown_seconds.value),maintenance_until:form.elements.maintenance_until.value?Math.floor(new Date(form.elements.maintenance_until.value).getTime()/1000):0});}
function workerRecords(){return table([t('nodeId'),t('workerName'),t('registrationVersion'),t('status'),t('lastSeen'),t('activeChecks'),''],adminWorkers.map(w=>[esc(w.id),esc(w.label||''),esc(w.reported_version||w.version||''),t(w.connection||'unknown'),w.last_seen?date(w.last_seen):t('noData'),w.active_checks?.map(c=>esc(c.name)).join(', ')||'—',w.source==='bootstrap'&&!w.revoked?`<button class="danger" data-action="revoke-worker" data-id="${esc(w.id)}">${t('revokeWorker')}</button>`:'']));}
setInterval(async()=>{if(!isAdmin||activeTab!=='workers'||document.hidden||document.querySelector('dialog[open]'))return;try{adminWorkers=await api('/api/admin/workers');const records=$('#worker-records');if(records)records.innerHTML=workerRecords();}catch{const records=$('#worker-records');if(records&&!$('.worker-refresh-error',records))records.insertAdjacentHTML('afterbegin',`<p class="worker-refresh-error muted">${t('errorRefresh')}</p>`);}},10000);
function trendMarkup(item,result,mode){
 const metric=mode!=='latency',field=metric?'metric_value':'latency_ms';const points=result.buckets.filter(b=>Number.isFinite(b[field]));if(!points.length)return `<p class="muted">${t('noData')}</p>`;
 const rules=metric?item.value_thresholds:null;const numbers=points.map(b=>b[field]);for(const n of [rules?.warning,rules?.critical])if(Number.isFinite(n))numbers.push(n);
 let min=Math.min(...numbers),max=Math.max(...numbers);const pad=max===min?Math.max(1,Math.abs(max)*.05):(max-min)*.1;min-=pad;max+=pad;
 const x=at=>36+((at-result.from)/(result.to-result.from))*708,y=v=>94-(v-min)/(max-min)*78;let path='',previous=null;
 for(const b of points){path+=(previous!==null&&b.at-previous<=result.precision?' L':' M')+x(Math.max(result.from,b.at)).toFixed(2)+' '+y(b[field]).toFixed(2);previous=b.at;}
 const lines=[['warning','degraded'],['critical','outage']].filter(([key])=>Number.isFinite(rules?.[key])).map(([key,cls])=>`<line class="${cls}" x1="36" x2="744" y1="${y(rules[key])}" y2="${y(rules[key])}"/><text x="738" y="${y(rules[key])-3}" text-anchor="end">${esc(rules[key])}</text>`).join('');
 const labels=points.filter((_,n)=>n%Math.max(1,Math.ceil(points.length/360))===0||n===points.length-1).map(b=>{const value=b[field];const label=`${date(b.at)} · ${t('trendAverage')} ${value.toFixed(2)}${metric?item.metric_unit:' ms'}${metric&&Number.isFinite(b.metric_min)?` · min ${b.metric_min} / max ${b.metric_max}`:''}`;return `<circle cx="${x(Math.max(result.from,b.at))}" cy="${y(value)}" r="3" tabindex="0" aria-label="${esc(label)}" data-bucket="${esc(label)}"/>`;}).join('');
 return `<svg class="trend-svg" viewBox="0 0 780 116" role="img" aria-label="${esc(item.name+' '+t('trend'))}"><text x="0" y="19">${max.toFixed(1)}</text><text x="0" y="94">${min.toFixed(1)}</text>${lines}<path d="${path}"/>${labels}</svg>`;
}

let monitorQuery='',monitorFilter='',monitorLocation='all';
function renderMonitors(){const root=$('#admin-content');root.innerHTML=`<div class="monitor-tools"><div class="monitor-search"><input id="monitor-search" type="search" value="${esc(monitorQuery)}" placeholder="${t('searchMonitors')}" aria-label="${t('searchMonitors')}"></div><select id="monitor-filter" aria-label="${t('status')}"><option value="">${t('allStatuses')}</option>${['operational','degraded','outage','unknown','disabled'].map(k=>`<option value="${k}" ${monitorFilter===k?'selected':''}>${t(k)}</option>`).join('')}</select><select id="monitor-location" aria-label="${t('workerLocation')}"><option value="all">${t('allAgents')}</option><option value="" ${monitorLocation===''?'selected':''}>${t('localNode')}</option>${adminWorkers.filter(w=>!w.revoked).map(w=>`<option value="${esc(w.id)}" ${monitorLocation===w.id?'selected':''}>${esc(w.label||w.id)}</option>`).join('')}</select></div><p class="monitor-result-count muted"></p><div id="monitor-list"></div><p class="footnote">${t('settingsHelp')}</p>`;renderMonitorList();}
function renderMonitorList(){const root=$('#monitor-list');if(!root)return;const query=monitorQuery.trim().toLowerCase();const items=adminItems.filter(i=>{const status=i.spec.enabled?i.status:'disabled';const node=adminWorkers.find(w=>w.id===i.spec.worker);return (!monitorFilter||status===monitorFilter)&&(monitorLocation==='all'||(i.spec.worker||'')===monitorLocation)&&(!query||[i.spec.name,i.spec.group,i.spec.description,i.spec.worker,node?.label].filter(Boolean).join(' ').toLowerCase().includes(query));});$('.monitor-result-count').textContent=`${items.length} / ${adminItems.length} ${t('matchingMonitors')}`;root.innerHTML=items.length?`<div class="services monitor-list">${items.map(i=>`<article class="admin-item monitor-row"><div class="item-info"><div class="monitor-tags"><span>${esc(i.spec.group)}</span><span>${esc(i.spec.kind.toUpperCase())}</span></div><h3>${esc(i.spec.name)}</h3>${i.spec.description?`<p class="monitor-description">${esc(i.spec.description)}</p>`:''}<small>${esc(i.spec.worker||t('localNode'))} · ${i.spec.cron?`${esc(i.spec.cron)} · ${esc(i.spec.schedule_timezone||'UTC')}`:`${i.spec.interval_seconds}s`} · ${i.last_check?date(i.last_check):t('noData')}</small></div>${state(i.spec.enabled?i.status:'disabled')}<div class="admin-actions">${(i.spec.kind==='push'?['edit','push-token','push-revoke','logs','delete']:['edit','run','logs','delete']).map(a=>`<button data-action="${a}" data-id="${i.id}" class="${a==='delete'?'danger':a==='edit'?'edit-action':''}">${t(a==='push-token'?'pushToken':a==='push-revoke'?'pushRevoke':a)}</button>`).join('')}</div></article>`).join('')}</div>`:adminItems.length?`<div class="empty"><h3>${t('noMatching')}</h3><button class="outline" data-action="clear-filters">${t('clearFilters')}</button></div>`:empty('noServices','noServicesHelp');}
if(isAdmin)document.body.classList.add('admin-view');

function inputPanel(data){return `<div class="panel"><h2>${t('inputsTab')}</h2><p>${t('inputHelp')}</p><p class="muted">${t('inputOwnedHelp')}</p><p><code>${esc(t('inputUse'))}</code></p>${data.vault_configured?`<form id="input-form" autocomplete="off"><div class="form-grid"><label>${t('inputName')}<input name="name" required maxlength="128" pattern="[A-Za-z0-9_]+" autocomplete="off"></label><label>${t('inputValue')}<input name="value" type="password" maxlength="65536" autocomplete="new-password"></label><label class="checkbox"><input name="enabled" type="checkbox" checked>${t('inputEnabled')}</label></div><button class="primary">${t('save')}</button></form>`:`<p>${t('vaultMissing')}</p>`}</div><div class="panel">${table([t('inputName'),t('inputEnabled'),t('inputStored'),t('inputSource'),''],data.inputs.map(i=>[esc(i.name)+(i.configured?`<small> · ${t('serverOwned')}</small>`:''),i.enabled?'✓':'—',i.stored?'✓':'—',esc(i.source),data.vault_configured&&i.editable?`<button data-action="input-replace" data-id="${esc(i.name)}" data-enabled="${i.enabled}">${t('inputReplace')}</button> ${i.stored?`<button class="danger" data-action="input-delete" data-id="${esc(i.name)}">${t('delete')}</button>`:''}`:'']))}</div>`;}

const zones=['UTC',...(Intl.supportedValuesOf?.('timeZone')||[])];if(displayTimezone&&!zones.includes(displayTimezone))zones.push(displayTimezone);$('#timezone').innerHTML=`<option value="">${t('systemTimezone')}</option>`+zones.map(z=>`<option value="${esc(z)}">${esc(z)}</option>`).join('');$('#timezone').value=displayTimezone;$('#schedule-timezones').innerHTML=zones.map(z=>`<option value="${esc(z)}"></option>`).join('');
function renderActionFields(actions){$('#check-actions').innerHTML=`<h3>${t('checkActions')}</h3><p class="muted">${t('actionHelp')}</p>`+['failure','success'].map(trigger=>{const a=actions.find(a=>a.trigger===trigger);const prefix='action_'+trigger+'_';const numbers=[['after_count','actionAfter',1,1,100],['delay_seconds','actionDelay',0,0,86400],['cooldown_seconds','actionCooldown',300,0,86400],['max_attempts','actionAttempts',1,1,5],['retry_seconds','actionRetry',30,1,86400],['wait_after_seconds','actionWait',0,0,86400],['timeout_seconds','timeout',30,1,300]];return `<details class="action-config" ${a?'open':''}><summary>${t(trigger==='failure'?'actionTriggerFailure':'actionTriggerSuccess')}</summary><div class="form-grid"><label>${t('kind')}<select name="${prefix}kind">${['','shell','python','lua','https'].map(k=>`<option value="${k}" ${(a?.kind||'')===k?'selected':''}>${k||t('actionOff')}</option>`).join('')}</select></label><label>${t('actionMode')}<select name="${prefix}mode"><option value="transition">${t('actionTransition')}</option><option value="repeat" ${a?.mode==='repeat'?'selected':''}>${t('actionRepeat')}</option></select></label><label class="full">${t('target')}<textarea name="${prefix}target" maxlength="16384" rows="3">${esc(a?.target||'')}</textarea></label><label class="full">${t('actionBody')}<textarea name="${prefix}body" maxlength="8192" rows="2">${esc(a?.body||'{"event":"{{ event }}","status":"{{ status }}","item_id":"{{ item_id }}"}')}</textarea></label><label class="full">${t('headersEnv')}<textarea name="${prefix}headers_env" rows="2">${esc(JSON.stringify(a?.headers_env||{}))}</textarea></label>${numbers.map(([name,label,value,min,max])=>`<label>${t(label)}<input name="${prefix}${name}" type="number" min="${min}" max="${max}" value="${a?.[name]??value}" required></label>`).join('')}</div></details>`;}).join('');}
function readActions(f){return ['failure','success'].flatMap(trigger=>{const p='action_'+trigger+'_';const kind=f.elements[p+'kind'].value;if(!kind)return [];const a={trigger,kind,mode:f.elements[p+'mode'].value,target:f.elements[p+'target'].value,body:f.elements[p+'body'].value,headers_env:JSON.parse(f.elements[p+'headers_env'].value||'{}')};for(const n of ['after_count','delay_seconds','cooldown_seconds','max_attempts','retry_seconds','wait_after_seconds','timeout_seconds'])a[n]=Number(f.elements[p+n].value);return [a];});}
$('#push-dialog').addEventListener('close',()=>{$('#push-token').value='';$('#push-example').textContent='';});
